    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placing the item
    let mut score = post_residual as f64;

    // 1. Penalize dead‑space when the next item cannot fit in this bin
    if next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64;
    }

    // 2. Penalize bins that leave a residual smaller than the current mean
    if post_residual < mean_residual as u32 {
        score += (mean_residual as u32 - post_residual) as f64;
    }

    // 3. Progress‑dependent pressure to use existing bins
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    // Earlier in the stream we are stricter about opening new bins
    score -= (open_bins_count as f64) * (1.0 - progress);

    // 4. Extra incentive when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= progress * (bin_capacity as f64);
    }

    // 5. For a brand‑new bin candidate, reward opening it only if we have many open bins already
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * (open_bins_count as f64);
    }

    score
}

