pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start with the post‑residual as the base score
    let mut score = post_residual as f64;

    // 1. Strict dead‑space avoidance:
    // Penalise bins that will leave a gap too small for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let diff = next_item_size - post_residual;
        score += 10.0 * diff as f64; // heavy penalty
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 5.0;
    }

    // 2. Open‑bin pressure:
    // Penalise opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        if open_bins_count > 1 {
            score += 5.0 * open_bins_count as f64;
        }
    }

    // 3. Penalise leaving more space than the current mean residual
    if post_residual as f64 > mean_residual {
        let excess = post_residual as f64 - mean_residual;
        score += 0.1 * excess;
    }

    // 4. Reward the bin that is the last possible fit
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // 5. Extra reward for bins that are almost full
    if post_residual < 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalised progress of the stream (0.0 .. 1.0)
    let progress = step_index as f64 / total_items as f64;

    // Non‑linear weight that decays as the stream progresses
    let weight = 1.0 + (1.0 - progress).powi(2);

    // Base score is the weighted residual after placing the item
    let mut score = post_residual as f64 * weight;

    // Penalise bins that would leave too little space for the next item
    let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
    score += gap.powi(2) * 0.5;

    // Mild penalty for having many open bins (encourage consolidation)
    score += (open_bins_count as f64).powi(2) * 0.01;

    // If this bin is the only fitting one, slightly discourage it when the residual is large
    let fit_factor = if fitting_bins_count > 0 {
        1.0 / fitting_bins_count as f64
    } else {
        0.0
    };
    score += fit_factor.powi(2) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: lower residual is better
    let mut score = post_residual as f64;

    // Penalize dead space that will block the next item
    if next_item_size > 0 && next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0; // dead‑space penalty factor
    }

    // Pressure from many open bins: discourage keeping many partially filled bins
    score += (open_bins_count as f64) * 0.5;

    // If this is the only bin that can fit the item, give a small bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Penalize bins with high average residual (wide gaps across all bins)
    if mean_residual > 20.0 {
        score += (mean_residual - 20.0) * 0.1;
    }

    // Slightly favor new bins when the stream is near its end
    let progress = (step_index as f64) / (total_items as f64);
    if progress > 0.9 && bin_residual == bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item
    let mut score = post_residual as f64;

    // Normalised progress of the stream
    let progress = step_index as f64 / total_items as f64;
    let pf = 1.0 - progress; // weight that fades as we go further

    // Reward bins that leave little residual space early in the stream
    score -= 0.5 * post_residual as f64 * pf;

    // Stronger reward for very small residuals (quadratic term)
    score -= 0.3 * (post_residual as f64).powi(2) * pf.powi(2);

    // Penalise bins that deviate from the average residual
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    // Penalise bins that cannot accommodate the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Strong reward when this is the last fitting bin
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 20.0 * last_chance * pf;

    // Encourage opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score -= 15.0 * pf;
    }

    // Slight penalty for having many open bins (to reduce fragmentation)
    score += 0.05 * open_bins_count as f64 * pf;

    score
}
